function triggerRecalculation() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet();
  const triggerCell = sheet.getSheetByName('Refresher').getRange("A1");
  const date = new Date();
  triggerCell.setValue(date.getTime());
  SpreadsheetApp.flush();
}

